check(LocalImageResolver.resolve("../assets/a.png",root:child)==nil && LocalImageResolver.resolve("../assets/a.png",root:child,allowedRoot:root)==assets.appendingPathComponent("a.png"),"rebased images resolve within selected workspace only")
