var writes=0
let outcome:Void?=try? plan.execute(["index.md":after,"another.md":after],directory:directory,writer:{data,url,baseline in writes+=1;if writes==2{throw CocoaError(.fileWriteNoPermission)};try FileStore.atomicWrite(data,to:url,baseline:baseline)})
let restoredIndex=try Data(contentsOf:index),restoredOther=try Data(contentsOf:another)
check(outcome==nil && restoredIndex==before && restoredOther==before && FileManager.default.fileExists(atPath:source.path) && !FileManager.default.fileExists(atPath:target.path),"second write failure rolls back earlier link writes and the move")
